macro_rules! normalize {
    () => {
        # [doc = " Resolve relative components virtually, eliminating intermediate `..` without accessing the filesystem."] # [doc = ""] # [doc = " For example, this turns `a/./b/c/.././..` into `a`, and turns `/a/../b/..` into `/`."] # [doc = ""] # [doc = " ```"] # [doc = " # fn main() {"] # [doc = " # use std::path::Path;"] # [doc = " # use gix_path::normalize;"] # [doc = " for (input, expected) in ["] # [doc = "     (\"a/./b/c/.././..\", \"a\"),"] # [doc = "     (\"/a/../b/..\", \"/\"),"] # [doc = "     (\"/base/a/..\", \"/base\"),"] # [doc = "     (\"./a/..\", \".\"),"] # [doc = "     (\"./a/../..\", \"/\"),"] # [doc = "     (\".///\", \".///\"),"] # [doc = "     (\"a//b\", \"a//b\"),"] # [doc = "     (\"/base/../base\", \"/base\"),"] # [doc = " ] {"] # [doc = "     let input = Path::new(input);"] # [doc = "     let expected = Path::new(expected);"] # [doc = "     assert_eq!(normalize(input.into(), Path::new(\"/cwd\")), Some(expected.into()));"] # [doc = " }"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " Leading `.` components as well as duplicate separators are left untouched."] # [doc = ""] # [doc = " This is particularly useful when manipulating paths that are based on user input, and not"] # [doc = " resolving intermediate symlinks keeps the path similar to what the user provided. If that's not"] # [doc = " desirable, use [`realpath()`](crate::realpath()) instead."] # [doc = ""] # [doc = " Note that we will use the `current_dir` if we run out of path components to pop off, which"] # [doc = " is expected to be absolute as typical return value of `std::env::current_dir()` or"] # [doc = " `gix_fs::current_dir(…)` when `core.precomposeUnicode` is known. As a `current_dir` like `/c`"] # [doc = " can be exhausted by paths like `../../r`, `None` will be returned to indicate the inability to"] # [doc = " produce a logically consistent path."] pub fn normalize < 'a > (path : Cow < 'a , Path > , current_dir : & Path) -> Option < Cow < 'a , Path > > { use std :: path :: Component :: ParentDir ; if ! path . components () . any (| c | matches ! (c , ParentDir)) { return Some (path) ; } let mut current_dir_opt = Some (current_dir) ; let was_relative = path . is_relative () ; let components = path . components () ; let mut path = PathBuf :: new () ; for component in components { if let ParentDir = component { let path_was_dot = path == Path :: new (".") ; if path . as_os_str () . is_empty () || path_was_dot { path . push (current_dir_opt . take () ?) ; } if ! path . pop () { return None ; } } else { path . push (component) ; } } if (path . as_os_str () . is_empty () || path == current_dir) && was_relative { Cow :: Borrowed (Path :: new (".")) } else { path . into () } . into () }
    };
}

normalize!();